INSERT INTO herbal_knowledge (herb_name, part_used, taste, properties) VALUES
    ('กกลังกา', 'ดอก', NULL, 'แก้โรคในปาก'),
    ('กกลังกา', 'ต้น', 'จืดเย็น', 'ขับปัสสาวะ ดับพิษไข้ แก้ร้อนในกระหายน้ำ และแก้น้ำเหลืองเสีย ทำลายดีอันผูกไว้ซึ่งพิษ'),
    ('กกลังกา', 'ใบ', NULL, 'ฆ่าแม่พยาธิทั้งปวง'),
    ('กกลังกา', 'ราก', NULL, 'กระทำให้โลหิตในท้องตกเสีย'),
    ('กกลังกา', 'หัว/เหง้า', NULL, 'เจริญอภิญญาณธาตุและอสุรินทญาณธาตุ สมุฏฐานพิกัตกระทำให้อาหารงวด กระทำเสมหะอันเฟื่องให้สงบลง'),
    ('กระชาย', 'หัว/เหง้า', 'เผ็ดร้อนขม', 'แก้ลำบองฝีคั่ง แก้โรคอันเกิดในปาก และแก้มุตกิด และลมอันบังเกิดแต่กองหทัยวาตะ'),
    ('กระชาย', 'เหง้า', 'เผ็ดร้อนขม หรือ เผ็ดร้อนขมปร่า', 'แก้ปวดมวนในท้อง แก้ชัก แก้ท้องอืด ท้องเฟ้อ บำรุงกำลัง บำรุงกำหนัด บำรุงกำลัง บำรุงกำหนัด แก้กษัย ขับลมในกระเพาะและลำไส้ แก้อาการแน่นจุกเสียด'),
    ('กระเช้าผีมด', 'ใบ/ต้น/ราก', NULL, 'ใช้ลดไข้ขับพิษ แก้ปวดบวม แก้อักเสบ กระเพาะอักเสบ ทางเดินปัสสาวะอักเสบ แก้บวมน้ำ'),
    ('กระเช้าผีมด', 'ราก', 'เมาเบื่อจืด', 'ขับพยาธิ แก้ปวดเมื่อยตามร่างกาย บำรุงหัวใจ'),
    ('กระดอม', 'ลูก', 'ขมจัด', 'บำรุงน้ำดี แก้ดีแห้ง ดีฝ่อ ดีเดือด เจริญอาหาร ทำให้โลหิตเย็น บำรุงมดลูกหลังแท้งหรือคลอดบุตร แก้มดลูกอักเสบ แก้ไข้'),
    ('กระดังงา', 'ราก', NULL, 'แก้หญิงไข้เพื่อโลหิต และลมระคนกัน และเสมหะพิการด้วยวาโยธาตุกำเริบให้จุกเสียดผอมเหลืองให้ไอ'),
    ('กระดาดแดง', 'หัว', 'เมาเบื่อคัน', 'กัดเสมหะ กัดเถาดาน กัดก้อนเนื้อร้าย แก้ริดสีดวง (ต้องสะตุก่อนใช้)'),
    ('กระทกรก', 'ราก', 'เผ็ดเล็กน้อย', 'แก้คูถเสมหะ แก้อุระเสมหะ ปรุงเป็นยาแก้ธาตุพิการ บำรุงธาตุ'),
    ('กระทุ้งหมาบ้า', 'ราก', NULL, 'ขับโลหิตอันเสียเหลวจางไปด้วยธาตุทั้ง 4 มิได้เสมอกัน'),
    ('กระเทียม', NULL, NULL, 'รสร้อน สรรพคุณแก้ไข้ ขับปัสสาวะ ขับโลหิตระดู เป็นยาระบาย แก้ไอ แก้ริดสีดวงงอก แก้โรคผิวหนัง เป็นยาขับลมในลำไส้ บำรุงธาตุ ใช้เป็นยาแก้โรคประสาท'),
    ('กระเทียม', 'จุก', 'ร้อน', 'แก้ไข้ ขับปัสสาวะ ขับโลหิตระดู เป็นยาระบาย แก้ไอ แก้ริดสีดวงงอก แก้โรคผิวหนัง เป็นยาขับลมในลำไส้ บำรุงธาตุ ใช้เป็นยาแก้โรคประสาท'),
    ('กระเทียม', 'ใบ', NULL, 'กระทำให้เสมหะแห้ง และกระจายโลหิต และแก้ลมอันปวดมวน'),
    ('กระเทียม', 'หัว', 'ร้อน', 'แก้ไข้ ขับปัสสาวะ ขับโลหิตระดู เป็นยาระบาย แก้ไอ แก้ริดสีดวงงอก แก้โรคผิวหนัง เป็นยาขับลมในลำไส้ บำรุงธาตุ ใช้เป็นยาแก้โรคประสาท แก้เสมหะและลม แก้เกลื้อนกลาก ให้ย่อยอาหารบำบัดโรคในอก กระทำให้ผมงาม แก้พรรดึกแก้ลมจุกเสียด'),
    ('กระบือ', 'น้ำนม', 'หวาน', 'กินแก้พรรดึก ให้เจริญรสอาหาร'),
    ('กระเบา', 'แก่น', NULL, 'แก้เสมหะให้ตก'),
    ('กระเบา', 'ดอก', NULL, 'ฆ่าแม่พยาธิ์อันเกิดแต่เกลื้อนและกลาก'),
    ('กระเบา', 'ใบ', NULL, 'แก้บาดแผลอันถูกหอกดาบ'),
    ('กระเบา', 'เปลือก', NULL, 'แก้ริดสีดวง'),
    ('กระเบา', 'ผล', NULL, 'แก้มะเร็งและคชราชโรคเรื้อนและกุฏฐัง'),
    ('กระเบา', 'ราก', NULL, 'แก้เสมหะอันมีพิษเน่าให้ไหลออกมา'),
    ('กระพังโหมตัวผู้', 'เถา', 'ขม', 'แก้ตานซาง ขับลม แก้ธาตุพิการ ขับพยาธิ บำรุงกำลัง สำหรับคนฟื้นไข้'),
    ('กระพังโหมตัวเมีย', 'เถา', 'จืด', 'แก้ตานซาง ขับลม แก้ธาตุพิการ ขับพยาธิ บำรุงกำลัง สำหรับคนฟื้นไข้'),
    ('กระลำพัก', 'แก่น', 'ขมหวานเย็นมัน', 'แก้ลมอังคะมังคานุสารี แก้ตรีสมุฏฐาน แก้โลหิตโทษ'),
    ('กระลำพัก', 'เนื้อไม้', NULL, 'ขมขื่นหอม บำรุงตับ บำรุงหัวใจ ดับพิษไข้ แก้ลมวิงเวียน และขับลม'),
    ('กระวาน', 'กะพี้', NULL, 'แก้โรคแต่ผิวหนัง'),
    ('กระวาน', 'แก่น', NULL, 'กระจายเสียซึ่งพิษทั้งปวง'),
    ('กระวาน', 'ดอก', NULL, 'แก้โรคอันบังเกิดในจักษุอันเปื่อยเน่า'),
    ('กระวาน', 'ใบ', NULL, 'แก้ไข้เพื่อวาโย, โลหิตและอาโปธาตุ กำเริบให้จุกเสียดเป็นก้อนในท้อง ให้นอนมิหลับให้มักโกรธ กระทำให้วาโยเดินลงเบื้องต่ำ และแก้ไข้อันเหงาง่วง แก้เสมหะ'),
    ('กระวาน', 'เปลือก', NULL, 'แก้ไข้อันเป็นอชินโรคและอชินธาตุ'),
    ('กระวาน', 'ผล', 'เผ็ดร้อนหอมปร่า หรือ ร้อนเผ็ดมีกลิ่นหอม', 'ขับลมในกระเพาะและลำไส้ แก้แน่นจุกเสียด บำรุงธาตุ และบำรุงหัวใจ กระจายซึ่งเสมหะและวาโยและโลหิต แก้ไข้เพื่ออากาศธาตุกำเริบ ให้ปวดศีรษะและร้อนกระบอกตาให้ท้องขึ้นและเจ็บกระดูกทุกข้อ แก้เสมหะแก้ลมในอกให้ปิดธาตุ'),
    ('กระวาน', 'ราก', NULL, 'สังหารเสียซึ่งโลหิตอันเน่าเป็นก้อนอยู่ในอุทรนั้นให้ตก'),
    ('กรักขี', 'แก่น', 'เผ็ดฝาด', 'บำรุงธาตุ บำรุงโลหิต ขับเสมหะ แก้เลือดออกตามไรฟัน แก้คุดทะลาด แก้บิดมูกเลือด'),
    ('กรุงเขมา', 'ราก', 'ขมหวานเย็น', 'ดับพิษไข้ ดับพิษร้อน บำรุงหัวใจ บำรุงน้ำดี และขับปัสสาวะ แก้ลมและโลหิต แก้กำเดา แก้จักษุโรค'),
    ('กฤษณา', 'เนื้อไม้', 'ขมหวานหอม', 'บำรุงหัวใจ บำรุงตับและปอด แก้ลมวิงเวียน ชูกำลัง และขับลม'),
    ('กล้วยตีบ', 'ราก', 'ฝาดเย็น', 'แก้ร้อนในกระหายน้ำ ขับปัสสาวะ บำรุงธาตุ เจริญอาหาร ดับพิษโลหิต'),
    ('กวาง', 'เขา', 'เค็มเย็นคาว', 'ดับพิษไข้กาฬ ดับพิษร้อน บำรุงโลหิต สมานกระดูก และแก้ช้ำใน'),
    ('กะตังบาย', 'ราก', NULL, 'แก้ฝีแดงและแก้ฝีกะตังบาย'),
    ('กะทือ', NULL, 'ขมขื่นปร่า', 'ขับลมในลำไส้ แก้แน่นจุกเสียด ท้องอืด ท้องเฟ้อ ขับน้ำคาวปลา และช่วยเจริญอาหาร'),
    ('กะทือ', 'ดอก', NULL, 'แก้ไข้อันผมเหลือง'),
    ('กะทือ', 'ต้น', NULL, 'แก้ไข้อันกระทำให้เบื่ออาหาร'),
    ('กะทือ', 'ใบ', 'ขมขื่นปร่าเผ็ดร้อน', 'ขับลมในลำไส้ แก้จุกแน่น แน่นเฟ้อ ปวดมวนท้อง ขับน้ำคาวปลา ขับฟอกโลหิตระดูสตรีแก้บิด บำรุงธาตุไฟ ช่วยเจริญอาหาร แก้เสมหะเหนียวข้น และบรรเทาอาการไอ แก้โลหิตอยู่ไฟให้ตก'),
    ('กะทือ', 'ราก', NULL, 'แก้ไข้อันร้อนกระทำให้เย็น'),
    ('กะทือ', 'หัว', NULL, 'ตั้งน้ำนมแห่งสตรีให้บริบูรณ์ขึ้น แก้ปวดมวนในอุทร ทำให้ฝีอ่อน หล่อมิให้หัวฝีแห้งเป็นตะกรันได้'),
    ('กะทือ', 'เหง้า', 'ขมขื่นปร่า', 'ขับลมในลำไส้ แก้แน่นจุกเสียด ท้องอืด ท้องเฟ้อ ขับน้ำคาวปลา และช่วยเจริญอาหาร'),
    ('กะทือป่า', 'เหง้า', NULL, 'เจริญไฟธาตุ แก้จุกเสียด'),
    ('กะเม็ง', 'ดอก', NULL, 'แก้ดีอันฟุ้งซ่านให้บริบูรณ์'),
    ('กะเม็ง', 'ต้น', NULL, 'ขับลมให้กระจาย แก้โลหิตอันกระทำให้ร้อน'),
    ('กะเม็ง', 'ใบ', 'เปรี้ยวอมหวาน', 'แก้อาเจียนเป็นโลหิต แก้จุกเสียดแน่น แก้โลหิตทำพิษให้ร้อน'),
    ('กะเม็ง', 'ผล', NULL, 'แก้ลมอันเป็นพิษให้ถอย'),
    ('กะเม็ง', 'ราก', NULL, 'แก้ลมวิงเวียนแก้ปวดในท้อง'),
    ('กัญชา', 'ใบ', 'เมาเบื่อหวานร้อน', 'ช่วยให้นอนหลับ เจริญอาหาร ระงับอาการปวดเกร็ง คลายกล้ามเนื้อ'),
    ('กัญชา', 'ใบ/ดอก', NULL, 'แก้ไข้ผอมเหลืองหากำลังมิได้ ให้ตัวสั่นเสียงสั่น เป็นด้วยวาโยธาตุกำเริบ แก้นอนมิหลับ'),
    ('กันเกรา', 'แก่น', 'เฝื่อนฝาดขม', 'แก้ไข้จับสั่น บำรุงธาตุ แก้หืด ไอมองคร่อ ริดสีดวง ท้องมาน แน่นหน้าอก ท้องเดิน มูกเลือด แก้พิษฝีกาฬ บำรุงม้าม บำรุงโลหิต แก้ปวดแสบ ปวดร้อน เป็นยาอายุวัฒนะ แก้ให้ประจำเดือนมาปกติในครั้งแรก แก้ไข้ให้จุกเสียด เพราะโลหิตเป็นก้อนอยู่ในท้อง และให้ผอมเหลืองจนถึงตาย'),
    ('กันเกรา', 'เปลือก', 'เฝื่อนฝาดขม', 'แก้ไข้จับสั่น บำรุงธาตุ แก้หืด ไอมองคร่อ ริดสีดวง ท้องมาน แน่นหน้าอก ท้องเดิน มูกเลือด แก้พิษฝีกาฬ บำรุงม้าม บำรุงโลหิต แก้ปวดแสบ ปวดร้อน เป็นยาอายุวัฒนะ'),
    ('กานพลู', 'ดอก', 'เผ็ดร้อนปร่า หรือ เผ็ดร้อนหวาน', 'เผ็ดร้อนปร่า กระจายเสมหะ แก้เสมหะเหนียว แก้เลือดออกตามไรฟัน แก้หืด ทำให้งวด แก้ปวดฟัน แก้รำมะนาด แก้ปวดท้อง แก้ลม แก้เหน็บชา แก้พิษโลหิต พิษน้ำเหลือง ขับน้ำคาวปลา ทำให้อุจจาระให้ปรกติ แก้ธาตุทั้ง 4 พิการ แก้ท้องเสีย กดลมให้สู่เบื้องต่ำ กระจายเสียซึ่งเสมหะอันข้น แก้เสมหะอันบังเกิดในกองโลหิตและดี แก้รัตตะปิตตะโรคแก้หืด และกระทำให้อาหารงวด แก้มวกในลำไส้ แก้เสมหะ แก้ลมจุกเสียด เจริญไฟธาตุ'),
    ('กาบหอยเผา', 'เถ้า', 'เค็มกร่อย', 'ขับนิ่วในไต ขับปัสสาวะ'),
    ('การบูร', 'ผลึก', 'เผ็ดร้อน หรือ ร้อนปร่าเมา หรือ เผ็ด', 'บำรุงธาตุ ทำให้อาหารงวด ขับลม ขับเสมหะ แก้ธาตุพิการ แน่นจุกเสียด ปวดท้อง ขับลมในลำไส้ กระจายทั้งปวง บำรุงธาตุ ทำให้อาหารงวด ขับเสมหะ แก้ธาตุพิการ แน่นจุกเสียด ปวดท้อง ขับลมในลำไส้ กระจายทั้งปวง ขับลม ช่วยเจริญอาหาร แก้โรคในอก แก้ลมทั้งปวง เจริญไฟธาตุและแก้เสมหะ'),
    ('การบูร', 'ผลึกขาว', 'เผ็ดร้อน', 'กระทำให้อาหารงวด แก้ลมคูถทวารให้เปิด ทำลายเสมหะ ให้ย่อยอาหารพลันแหลก แก้จักษุโรค แก้ริดสีดวง กระทำให้รู้จักรสอาหาร แก้ลมจุกเสียดแก้หืดไอ'),
    ('กำจาย', 'ราก', NULL, 'กระจายหัวฝี'),
    ('กำมะถันเหลือง', NULL, 'เปรี้ยวเหม็นปร่า', 'ฆ่าเชื้อโรค ฆ่าพยาธิ รักษาโรคผิวหนัง กลาก เกลื้อน หิด แผลเปื่อยเรื้อรัง'),
    ('กำลังโคเถลิง', 'แก่น', 'มันร้อนติดฝาด', 'บำรุงโลหิต บำรุงธาตุ บำรุงเส้นเอ็น แก้ปวดเมื่อยตาม ร่างกาย บำรุงกำลัง บำรุงกระดูกให้แข็งแรง เป็นยาอายุวัฒนะ'),
    ('กำลังโคเถลิง', 'เนื้อไม้', 'มันร้อนติดฝาด', 'บำรุงโลหิต บำรุงธาตุ บำรุงเส้นเอ็น แก้ปวดเมื่อยตาม ร่างกาย บำรุงกำลัง บำรุงกระดูกให้แข็งแรง เป็นยา อายุวัฒนะ'),
    ('กำลังวัวเถลิง', 'แก่น', 'มันร้อนติดฝาด', 'สรรพคุณบำรุงโลหิต บำรุงธาตุ บำรุงเส้นเอ็น แก้ปวดเมื่อยตาม ร่างกาย บำรุงกำลัง บำรุงกระดูกให้แข็งแรง เป็นยา อายุวัฒนะ'),
    ('กำลังหนุมาน', NULL, 'ขมมัน', 'แก้น้ำดีพิการ นอนสะดุ้ง ผวา หลับๆตื่นๆ ร้อนหน้า น้ำตาไหล บำรุงกำลัง'),
    ('กุ่มน้ำ', 'แก่น', NULL, 'แก้ปะระเมหะ คือนิ่ว'),
    ('กุ่มน้ำ', 'ดอก', NULL, 'แก้เจ็บในลำคอ'),
    ('กุ่มน้ำ', 'ใบ', NULL, 'กระทำให้เหงื่อซ่านออกมา'),
    ('กุ่มน้ำ', 'เปลือก', 'ร้อน', 'ขับลม แก้นิ่ว แก้ปวดท้อง ลงท้อง คุมธาตุ บำรุงไฟธาตุ แก้บวมใช้ทาภายนอกแก้โรคผิวหนัง แก้สะอึก และแก้ลมให้เร็วขึ้นเบื้องบน'),
    ('กุ่มน้ำ', 'ผล', NULL, 'แก้ไข้อันกระทำให้หนาวและร้อน'),
    ('กุ่มน้ำ', 'ราก', NULL, 'ทำลายบุพโพอันผูกเป็นก้อน'),
    ('กุ่มบก', 'แก่น', NULL, 'แก้ริดสีดวงผอมเหลือง'),
    ('กุ่มบก', 'ใบ', NULL, 'แก้ลมและฆ่าแม่พยาธิตะมอย แก้เกลื้อนอันบังเกิดขึ้นที่หน้า'),
    ('กุ่มบก', 'เปลือก', 'ร้อน', 'ขับลม แก้นิ่ว แก้ปวดท้อง ลงท้อง คุมธาตุ บำรุงไฟธาตุ แก้บวมใช้ทาภายนอกแก้โรคผิวหนัง แก้นิ่วและลมอันกระทำให้เย็นในท้อง'),
    ('กุ่มบก', 'ราก', 'ร้อน', 'ขับลม แก้นิ่ว แก้ปวดท้อง ลงท้อง คุมธาตุ บำรุงไฟธาตุ แก้บวม ใช้ทาภายนอกแก้โรคผิวหนัง แก้มานกษัย อันบังเกิดแต่กองลม'),
    ('เกลือประสะ', 'ผลึกสีขาว', 'หวาน', 'ย่อยอาหารให้พลันแหลกแก้ร้อนผายธาตุ แก้พิษ แก้กำเดา แก้ลมจุกเสียด'),
    ('เกลือฝ่อ', 'ผลึกสีขาว', NULL, 'แก้โรคอันเสียดแทงบำรุงไฟธาตุ แก้กุมารโรคและแก้พรรดึก แก้มูกเลือดให้อันตรธานวิเศษนัก'),
    ('เกลือพิก', 'ผลึกสีขาว', NULL, 'กระทำให้เสียงเพราะให้ชุ่มในลำคอ'),
    ('เกลือวิก', 'ผลึกสีขาว', NULL, 'แก้อภิญญาณธาตุ ทำลายเสียซึ่งโรคในท้องคือท้องมาน แก้ไส้พองท้องใหญ่กระทำให้กายชุ่มชื่น'),
    ('เกลือสมุทร', 'ผลึก', 'เค็มสุขุม', 'ชำระเมือกมัน กัดเสมหะในลำคอ บำรุงธาตุ ช่วยย่อยอาหาร และเป็นยาระบายอ่อนๆ'),
    ('เกลือสมุทะรี', 'ผลึกสีขาว', NULL, 'กระทำให้อาหารงวด แก้ระส่ำระสายเจริญธาตุทั้ง 4 แก้พรรดึกและแก้ดีเดือด แก้โรคอันบังเกิดแต่ตา'),
    ('เกลือสินเธาว์', 'ผลึก', 'เค็ม', 'ทำลายพรรดึก แก้ระส่ำระสาย แก้สมุฏฐานตรีโทษ แก้นิ่ว ขับพยาธิภายในท้องล้างเมือกมันภายใน รู้ทำลายพรรดึก แก้ระส่ำระสาย แก้สมุฎฐานตรีโทษ แก้นิ่ว ขับพยาธิภายในท้องล้างเมือกมันภายใน'),
    ('เกลือสินเธาว์', 'ผลึกสีขาว', 'เค็ม', 'แก้กำเดาและลมจุกเสียด แก้พรรดึกและไข้ตรีโทษ'),
    ('แกแล', 'แก่น', 'หวานชุ่มขมฝาด', 'บำรุงน้ำเหลือง บำรุงโลหิต ขับน้ำเหลืองเสีย ดับพิษไข้ และแก้กษัย'),
    ('แกะ', 'น้ำนม', NULL, 'แก้หืดไอและจุกเสียด เจริญไฟธาตุ'),
    ('โกฐกระดูก', NULL, NULL, 'แก้ลมในเสมหะสมุฏฐาน แก้ลมอัมพฤกษ์ กระทำให้คลื่นเหียนให้จุกเสียดให้หูตึงให้ตามืด'),
    ('โกฐกะกลิ้ง', NULL, NULL, 'แก้ไข้เพื่อเสมหะพิการ ด้วยลมอุทธังคมาวาตา และกำเดากำเริบ ให้ปวดศีรษะมีน้ำมูกมากให้ตาแดง ให้ผูกพรรดึก แก้โรคในปากในคออันประกอบไปด้วยกิมิชาติ แก้ไข้ในทางปัสสาวะให้สะดวก และแก้พิษงูตะขาบและแมลงป่อง แก้ลมอันกระทำให้กระเพื่อมในอุทร และคลื่นเหียน สมมุติว่าลมพานไส้ แก้ริดสีดวงทวาร และแก้โลหิตอันกระทำให้เย็นและกระจายเสียซึ่งลมผูกกลัดทวาร และลมกำเริบในท้อง'),
    ('โกฐกักกรา', NULL, NULL, 'แก้ลมอันทำให้คลื่นเหียนและ แก้ดีพิการ แก้ริดสีดวงอันงอกในทวารทั้ง 9'),
    ('โกฐก้านพร้าว', NULL, 'เย็น หรือ ขม', 'เย็น แก้ไข้ แก้หอบ แก้สะอึก แก้เสมหะเป็นพิษ แก้สะอึก แก้อาเจียน แก้เสมหะ แก้ลม แก้ไข้สำประชวร แก้กำเดาแก้ไข้จับอันประกอบให้สะอึก และแก้เสมหะแก้หอบ แก้โลหิตพิการ โลหิตดำบ้างเหลวบ้าง เป็นฟองบ้าง ให้จับเชื่อมมัวให้เมื่อยทั่วสรรพางค์'),
    ('โกฐเขมา', NULL, 'ร้อน', 'ยาบำรุงธาตุ ยาบำรุงใช้แก้โรคเข้าข้อ เป็นยาเจริญอาหาร ยาขับปัสสาวะ แก้โรคในปากในคอ และแก้หอบให้เสียดแทงสีข้างทั้งสอง แก้ลมอุทธังคมาวาตาเพื่อลมอันบังเกิดแต่กองอาโปธาตุ ให้มือให้เท้าสั่นให้เมื่อยขบทั่วตัว'),
    ('โกฐจุฬารส', NULL, NULL, 'กระจายบุพโพ อันเป็นก้อน ฆ่าเสียซึ่งแม่พยาธิอันบังเกิดแต่ไส้ด้วนไส้ลาม อุปทม ขับโลหิตอันเน่าให้ตกและแก้รัตตะปิตตะโรค สังหารเสียซึ่ง โลหิตอันบังเกิดแต่กองปิตตะสมุฏฐาน กระจายเสียซึ่งสรรพพิษ'),
    ('โกฐจุฬาลัมพา', NULL, 'ขมเล็กน้อย', 'แก้ไข้ แก้ไข้จับสั่นแก้ไข้เจลียง แก้ไข้ ลดเสมหะ แก้หืด แก้ไอ ใช้เป้นยาขับเหงื่อ แก้ไข้ แก้ไข้จับสั่น(ไข้ป่า)แก้ไข้เจลียง แก้ไข้ ลดเสมหะ แก้หืด แก้ไอ ใช้เป้นยาขับเหงื่อ'),
    ('โกฐจุฬาลำพา', NULL, 'ขมเล็กน้อย หรือ ขม', 'แก้ไข้ แก้ไข้จับสั่นแก้ไข้เจลียง แก้ไข้ ลดเสมหะ แก้หืด แก้ไอ ใช้เป้นยาขับเหงื่อ แก้ไข้เจลียง และแก้ผื่นพรึง ขึ้นทั้งตัว เป็นเพื่อเสมหะและหืดไอ แก้ลมอันมิได้เสมอเป็นปรกติ กระทำให้ร้อนให้เย็นแต่เป็นเหงื่อไหล'),
    ('โกฐเชียง', NULL, 'หวานขม', 'แก้ไข้ แก้สะอึก แก้เสียดแทงราวข้าว บำรุงเลือด บำรุงร่างกาย แก้ไข้ให้สะอึกและให้ไอให้เสียดแทงสองราวข้าง'),
    ('โกฐเชียงเทศ', NULL, NULL, 'แก้ไข้เพื่อกำเดา ให้หนาวให้ร้อนให้ระส่ำระสาย ให้ท้องขึ้นกินอาหารมิได้เหงื่อตกให้หอบ'),
    ('โกฐน้ำเต้า', NULL, NULL, 'แก้พิษอันกระทำให้ธาตุมั่นและแก้อุจจาระปัสสาวะให้บริบูรณ์'),
    ('โกฐบัว', NULL, NULL, 'แก้ลมในกองริดสีดวงและกระจาย ซึ่งสรรพลมทั้งปวง'),
    ('โกฐพุงปลา', NULL, 'ฝาดจัด', 'แก้อุจจาระธาตุพิการ แก้อติสาร แก้บิดมูกเลือด คุมธาตุ แก้ไข้จากลำไส้อักเสบ แก้ไข้พิษ แก้พิษทำให้ร้อน แก้อาเจียน แก้เสมหะพิการ แก้เม็ดยอดภายใน แก้ไข้ในกองอติสารและอุจจาระธาตุและแก้พิษอันทำให้ร้อนเป็นกำลัง แก้โลหิตพิการและเสมหะพิการ ให้ท้องขึ้นให้จุกอกกินข้าวและน้ำแค้น ในทรวงอก เป็นเพื่อลมอังคมังคานุสารีวาต'),
    ('โกฐสอ', NULL, 'ขมมัน หรือ ฝาดขม', 'แก้ไข้ แก้หืด แก้ไอ ทำให้หัวใจชุ่มชื่น แก้ไข้จับและหืดไอ และลมอัมพฤกษ์ ให้ร้อนเท้าให้ร้อนหลังให้แสบอกให้เจ็บสะบัก'),
    ('โกฐหัวบัว', NULL, 'มัน', 'แก้ลมในกองริดสีดวง และกระจายลมทั้งปวง'),
    ('ขนุน', 'แก่น', 'หวานชุ่มฝาดขม', 'บำรุงกำลัง บำรุงโลหิต บำรุงน้ำนมในสตรีหลังคลอด สมานแผล สมานลำไส้ แก้ท้องเสีย ท้องร่วง บำรุงร่างกาย ชูกำลัง แก้กษัยขับพยาธิ และแก้กามโรค แก้อาโปธาตุกำเริบ และโลหิตพิการเมื่อยขบทั่วสรรพางค์ เวลาเช้าให้ท้องขึ้นไม่รู้รสอาหารให้เหม็นผักปลา'),
    ('ขมิ้นเครือ', 'แก่น', 'เฝื่อนฝาดขม', 'บำรุงน้ำเหลือง ขับโลหิตระดูสตรี แก้ดีซ่าน'),
    ('ขมิ้นเครือ', 'ดอก', NULL, 'แก้บิดและมูกเลือด'),
    ('ขมิ้นเครือ', 'ต้น', NULL, 'กระจายลมอันบังเกิดแต่ดี แก้เสมหะและไข้ตรีโทษ'),
    ('ขมิ้นเครือ', 'เถา', 'เผ็ดร้อน', 'แก้พิษโลหิตและลม แก้บวม แก้เสมหะ แก้ไข้ทั้งปวง แก้ตัวพยาธิ์กระทำให้คันทั่วกาย แก้ฝีแก้เสมหะและลม แก้กระหายน้ำ'),
    ('ขมิ้นเครือ', 'ใบ', NULL, 'แก้โลหิตเน่าให้ตก'),
    ('ขมิ้นเครือ', 'ราก', NULL, 'ขับลมอัมพฤกษ์ให้ตก'),
    ('ขมิ้นเครือ', 'ลำต้น/เถา', 'เฝื่อนฝาดขม', 'บำรุงน้ำเหลือง ขับโลหิตระดูสตรี แก้ดีซ่าน'),
    ('ขมิ้นชัน', 'เหง้า', 'ฝาดเฝื่อนเผ็ดร้อน หรือ เผ็ดร้อน', 'แก้จุกเสียด แน่นท้อง อาหาร แก้ไข้อันบังเกิดแต่ดี ชำระโรคอันบังเกิดตามผิวหนัง ระงับแตโชธาตุให้ดับ แก้เสมหะทำให้ฟกบวมและแก้บาดแผล แก้พิษโลหิตและลม แก้บวม แก้เสมหะ แก้ไข้ทั้งปวง แก้ตัวพยาธิ์กระทำให้คันทั่วสรรพางค์ แก้ฝี แก้ลมอุทธังคมาวาต ลมปัสสคาด แก้โลหิตและเสมหะ แก้เจ็บทุกข้อทุกกระดูก แก้พิษโลหิตและลม แก้บวม แก้เสมหะ แก้ไข้ทั้งปวง แก้ตัวพยาธิ์กระทำให้คันทั่วกาย แก้ฝี แก้โลหิตมิให้แพร่ออกจากหัวฝี'),
    ('ขมิ้นอ้อย', 'เหง้า', 'ฝาดเฝื่อน', 'ฝาดเฝื่อน แก้ครั่นเนื้อครั่นตัว สมานลำไส้ แก้ระดูขาว ขับปัสสาวะ'),
    ('ขอนดอก', 'แก่น', 'เผ็ดจืด', 'แก้เสมหะแก้เหงื่อและไข้ร้อนเพื่อตรีโทษ'),
    ('ขัณฑสกร', 'ผลึก', 'หวานเย็น', 'กินเจริญเสมหะดี แก้อาเจียน แก้ระหายน้ำ'),
    ('ขัดมอน', 'ราก', 'เผ็ด', 'แก้พิษไข้ ไข้กาฬ แก้ไข้หัด สุกใส ดำแดง ฝีดาษ แก้ร้อนใน แก้ เยื่อหุ้มสมองอักเสบ แก้ปวดมดลูก แก้ไข้เพื่อโลหิตพิการ ให้เหม็นเน่าเหม็นคาว เป็นก้อนขัดอยู่เดินมิสะดวกกระทำให้ร้อน'),
    ('ขันทองพยาบาท', 'แก่น', 'เมาเบื่อร้อน', 'แก้ลม แก้ประดง แก้พิษในกระดูก แก้โรคผิวหนัง รักษาน้ำเหลืองเสีย'),
