    ('สุพรรณกันแดง', NULL, 'ปร่า', 'รู้แก้ลมป่วง รู้แก้หัวฝีและรักษาท้อง เข้ายาต้ม แก้ประดง ใช้หุงกับน้ำมันใส่แผลเรื้อรัง แผลเปื่อยลาม'),
    ('สุพรรณถันเหลือง', NULL, NULL, 'รสปร่า รู้แก้ลมป่วง รู้แก้หัวฝีและรักษาท้อง เข้ายาต้ม แก้ประดง ใช้หุงกับน้ำมันใส่แผลเรื้อรัง แผลเปื่อยลาม แผลเรื้อรังมักใช้ร่วมกับสุพรรณถัน'),
    ('สุพรรณทลิกา', NULL, 'หวาน', 'แก้ผอมแห้ง ให้กายสมบูรณ์ให้รู้จักรสอาหาร และแก้ลมเลือดพิการให้ปิดธาตุ'),
    ('สุรา', NULL, 'เผ็ดร้อนขม', 'สรรพคุณเป็นน้ำกระสายยานำแทรกตัวยาเข้าสู่เส้นโลหิตและหัวใจอย่างรวดเร็ว กระจายเลือดลม ขับลมในลำไส้ ขับเหงื่อ ช่วยเจริญอาหาร บำรุงธาตุไฟให้ลุกโพลง ระงับอาการปวดเมื่อยเส้นเอ็น และกระตุ้นการไหลเวียนโลหิต'),
    ('สุรา', 'น้ำ', 'เผ็ดร้อนขม', 'เป็นน้ำกระสายยานำแทรกตัวยาเข้าสู่เส้นโลหิตและหัวใจอย่างรวดเร็ว กระจายเลือดลม ขับลมในลำไส้ ขับเหงื่อ ช่วยเจริญอาหาร บำรุงธาตุไฟให้ลุกโพลง ระงับอาการปวดเมื่อยเส้นเอ็น และกระตุ้นการไหลเวียนโลหิต'),
    ('สุรา', 'น้ำกระสายยา', 'เผ็ดร้อนขม', 'นำแทรกตัวยาเข้าสู่เส้นโลหิตและหัวใจอย่างรวดเร็ว กระจายเลือดลม ขับลมในลำไส้ ขับเหงื่อ ช่วยเจริญอาหาร บำรุงธาตุไฟให้ลุกโพลง ระงับอาการปวดเมื่อยเส้นเอ็น และกระตุ้นการไหลเวียนโลหิต'),
    ('เสนียด', 'ดอก', 'ขมเย็น', 'ดับพิษไข้ แก้ตาแดง บำรุงสายตา และบรรเทาอาการไอ'),
    ('เสนียด', 'ต้น', 'ขมเฝื่อน', 'แก้ไอ ละลายเสมหะ บรรเทาอาการหลอดลมอักเสบ และขับเสมหะ'),
    ('เสนียด', 'ใบ', 'ขมเฝื่อน', 'แก้ไอ ขับเสมหะ ระงับหอบหืด ดับพิษฝี และรักษาแผลอักเสบ แก้แผลในลำคอและแก้คอเป็นโรคดุจหนามก้านบัว แก้แม่พยาธิในไรฟัน ห้ามเสียซึ่งรัตตะปิตตะโรคและไข้จับ แก้คชราชและฟกบวม กระทำ ผิวหนังให้ผ่องใส'),
    ('เสนียด', 'ผล', 'ขมเฝื่อน', 'ขับเสมหะ แก้ไอ ขับลม และระงับอาการหอบหืด'),
    ('เสนียด', 'ราก', 'ขมเฝื่อน', 'ดับพิษไข้ ขับเสมหะ บรรเทาอาการไอ ระงับหอบหืด และฟอกโลหิต แก้ไข้เพื่อลมกำเริบ ให้ตัวร้อนผอมเหลือง'),
    ('เสนียด', 'ราก) (ใบ) (ดอก', 'ขม', 'แก้หืดไอแก้ไข้สำประชวร แก้โลหิต แก้บิด แก้พิษฝี แก้รัตตะ ปิตตะ'),
    ('แสมทะเล', 'แก่น', 'เค็มเฝื่อน หรือ เค็ม', 'แก้ลมในกระดูก แก้กษัย ฟอกและขับโลหิต แก้ปวดเมื่อยเส้นเอ็น ถ่ายเสมหะ แก้ปัสสาวะพิการ แก้กษัย ขับโลหิต ขับน้ำคาวปลา ขับลม'),
    ('แสมสาร', 'แก่น', 'ขมเอียนเปรี้ยวเค็ม', 'ถ่ายเสมหะ ถ่ายพิษโลหิต ขับฟอกโลหิตระดูสตรี ฟอกโลหิต และเป็นยาระบายอุจจาระธาตุ'),
    ('หญ้าขัดมอน', 'ราก', NULL, 'แก้อาเจียนคลื่นเหียน'),
    ('หญ้าคา', 'ราก', 'หวานจืดเย็น', 'ขับปัสสาวะ แก้น้ำปัสสาวะขัด แก้ปัสสาวะเป็นเลือด ดับพิษไข้ แก้ไข้ตัวร้อน ดับพิษกาฬ แก้ร้อนใน กระหายน้ำ ห้ามเลือดกำเดาไหล แก้บวมน้ำ บำรุงไต และลดความร้อนสะสมในร่างกาย'),
    ('หญ้างวงช้าง', 'ราก/ทั้งต้น', 'เย็น', 'แก้พิษตานซาง ลดไข้ในเด็ก แก้กระหายน้ำ ละลายก้อนนิ่ว แก้โรคตา'),
    ('หญ้าชันกาด', 'หัว', 'หวานเย็นจืด', 'ขับปัสสาวะ แก้น้ำปัสสาวะขัด แก้กระษัยน้ำเบา ขับนิ่วในทางเดินปัสสาวะและกระเพาะปัสสาวะ ดับพิษไข้ แก้ร้อนในกระหายน้ำ บำรุงไต และแก้อาการบวมน้ำ'),
    ('หญ้าไช', 'ทั้งต้น', 'จืดเย็นขม', 'ดับพิษไข้ ถอนพิษตานซาง ขับปัสสาวะ และแก้น้ำเหลืองเสีย'),
    ('หญ้าไชดำ', 'ทั้งต้น', 'จืดเย็นขม', 'ดับพิษไข้ ถอนพิษตานซาง ขับปัสสาวะ และแก้น้ำเหลืองเสีย'),
    ('หญ้าไซ', NULL, 'จืดเย็นขม', 'ดับพิษไข้ ถอนพิษตานซาง ขับปัสสาวะ และแก้น้ำเหลืองเสีย'),
    ('หญ้าตีนกา', 'ทั้งต้น', 'ขมเย็น', 'สรรพคุณลดความร้อน แก้พิษไข้กาฬ บำรุงหัวใจ'),
    ('หญ้าตีนนก', 'ทั้งต้น', NULL, 'แก้ไข้อันกระทำให้ร้อนระหายน้ำเป็นเพื่อดีแห้ง แก้ลม แก้โลหิต เสมหะเป็นตรีโทษ กระทำให้ตัวร้อนสะท้านหนาว ให้เจ็บมีเวลา และหาเวลามิได้ ให้ครั่นตัวปวดศีรษะตาพร่างพราย'),
    ('หญ้าปากควาย', 'ทั้งต้น', 'หวานจืดเย็น', 'ดับพิษไข้ แก้ร้อนในกระหายน้ำ ขับปัสสาวะ และแก้พิษตานซาง'),
    ('หญ้าพันงู', 'ดอก', NULL, 'แก้เสมหะในท้อง'),
    ('หญ้าพันงู', 'ต้น', NULL, 'แก้ทางปัสสาวะอันขัดขัง'),
    ('หญ้าพันงู', 'ใบ', NULL, 'แก้โรคในลำคอดุจหนามก้านบัว'),
    ('หญ้าพันงู', 'ผล', NULL, 'ทำลายเม็ดนิ่วให้ตก'),
    ('หญ้าพันงู', 'ราก', NULL, 'แก้นิ่ว 20 ประการ'),
    ('หญ้าแพรก', NULL, 'ขมเย็น', 'แก้พิษเจ็บปวด แก้อักเสบ แก้สตรีตกโลหิตมากเกินไป แก้ร้อนในกระหายน้ำ แก้ไข้พิษไข้กาฬ ไข้หัด สุกใส ดำ แดง'),
    ('หญ้าแพรก', 'ทั้งต้น', 'ขมเย็น', 'แก้พิษเจ็บปวด แก้อักเสบ แก้สตรีตกโลหิตมากเกินไป แก้ร้อนในกระหายน้ำ แก้ไข้พิษไข้กาฬ ไข้หัด สุกใส ดำ แดง แก้ลมและโลหิต บดเป็นยารมแก้ตัวพยาธิซึ่ง กระทำให้คันตัวทั่วสรรพางค์ แก้สรรพพิษอันกระทำให้คันและร้อน แก้รัตตะปิตตะโรคและแก้ฝีดาษ'),
    ('หญ้าแพรก', 'ราก/ทั้งต้น', 'ขมเย็น', 'แก้พิษเจ็บปวด แก้อักเสบ แก้สตรีตกโลหิตมากเกินไป แก้ร้อนในกระหายน้ำ แก้ไข้พิษไข้กาฬ ไข้หัด สุกใส ดำ แดง'),
    ('หญ้าหนวดแมว', 'ใบ', NULL, 'แก้ลมอัณฑพาธ แก้โลหิตพิการ กระทำให้คันในเนื้อและหนังพอขึ้นมีพิษต่างๆ'),
    ('หญ้าหนวดแมว', 'ใบ/ทั้งต้น', 'จืดเย็นขื่น', 'ขับปัสสาวะ ขับนิ่วในไตและกระเพาะปัสสาวะ แก้กระษัยไตพิการ ดับพิษร้อน'),
    ('หนอนตายหยาก', 'ราก', 'เมาเบื่อขมร้อน', 'ฆ่าหนอน ฆ่าเหา ฆ่าพยาธิ รักษาโรคผิวหนังและแผลเรื้อรัง'),
    ('หนามทั้งสอง', 'ราก', 'ขมขื่นเฝื่อน', 'ดับพิษร้อน ถอนพิษไข้ ดับพิษกาฬ แก้น้ำเหลืองเสีย แก้ประดง ผื่นคันตามผิวหนัง ขับปัสสาวะ แก้กษัย และขับลมในเส้นเอ็น'),
    ('หมอน้อย', 'ราก', 'ขมเอียน', 'ขับปัสสาวะ ดับพิษไข้ ดับพิษร้อน แก้ไอ ระงับหอบ ขับเสมหะและบรรเทาการอักเสบในลำคอ แก้บิด ท้องเสีย แก้ปวดมวนในท้อง แก้ริดสีดวงทวาร สมานแผล และช่วยลดความอยากบุหรี่'),
    ('หอม', 'หัว', 'หวานเผ็ด', 'แก้ไข้อันเกิดแต่ทรวง กระทำให้ผมดก กระทำให้อาหารงวด แก้ไข้สันนิบาตและไข้อันบังเกิดแต่จักษุกระทำให้เสมหะตก แก้โรคในปากและบำรุงธาตุ แก้ไข้หวัดและไข้อันผูกเป็นเจ้าเรือนและแก้ไข้'),
    ('หอมแดง', 'หัว', 'หวานเค็ม', 'แก้ไข้หวัดแลไข้อันผูกเป็นเจ้าเรือนแลแก้ไข้ แก้ลมอากาศธาตุ ให้ท้องขึ้นและคันทั่วกายให้ตาพร่าง และไฟธาตุกำเริบกระทำให้กินอาหารมากนัก'),
    ('หอยกาบ', 'เปลือก', 'เค็มกร่อย', 'ขับนิ่วในไต ขับปัสสาวะ'),
    ('หอยกาบเผา', 'เถ้า', 'เค็มกร่อย', 'ขับนิ่วในไต ขับปัสสาวะ'),
    ('หอยขม', 'เปลือก', 'เค็มกร่อย', 'ขับนิ่วในไต ขับปัสสาวะ'),
    ('หอยขมเผา', 'เถ้า', 'เค็มกร่อย', 'ขับนิ่วในไต ขับปัสสาวะ'),
    ('หอยโข่ง', 'เปลือก', 'เค็มกร่อย', 'ขับนิ่วในไต ขับปัสสาวะ'),
    ('หอยแครง', 'เปลือก', 'เค็มกร่อย', 'ขับนิ่วในไต ขับปัสสาวะ'),
    ('หอยแครงเผา', 'เถ้า', 'เค็มกร่อย', 'ขับลมในลำไส้ ล้างลำไส้ แก้กษัย ขับนิ่ว ขับปัสสาวะ แก้ไตพิการ ช่วยลดกรดในกระเพาะอาหาร แก้ท้องอืดเฟ้อ'),
    ('หอยแครงเผา', 'เปลือก', 'เค็มกร่อย', 'ขับนิ่วในไต ขับปัสสาวะ'),
